namespace {
float number(jass::Real v){return std::bit_cast<float>(v.bits());}
jass::Real real(float v){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(v));}
float distance(const UnitState& u,WorldPoint p){return std::hypot(number(u.x)-number(p.x),number(u.y)-number(p.y));}
}
std::vector<std::uint32_t> ScriptSession::spellTargets(std::uint32_t source,const SpellInfo& s,WorldPoint point,unsigned owner) {
    std::vector<std::pair<float,std::uint32_t>> candidates;if(!alive(source,NativeKind::Unit))return {};auto caster=units_.at(source);for(auto& [id,u]:units_){float d=distance(*u,point);if(d<=s.area+u->collision && spellTarget(*caster,*u,s,false,owner))candidates.emplace_back(d,id);}std::sort(candidates.begin(),candidates.end());std::vector<std::uint32_t> result;for(auto [d,id]:candidates)result.push_back(id);return result;
}
void ScriptSession::releaseSpell(std::uint32_t source,const CastOrder& cast,unsigned owner) {
    if(!alive(source,NativeKind::Unit))return;auto u=units_.at(source);auto& s=cast.spell;if(!s.unorder || s.order!=s.unorder)queueSpellSound(s.ability,{u->x,u->y});if(spellShield(source,cast.target,s,owner))return;if(s.kind==SpellKind::ShadowSight){if(alive(cast.target,NativeKind::Unit) && spellTarget(*u,*units_.at(cast.target),s,false,owner)){applyBuff(cast.target,source,s,BuffKind::ShadowSight);++fogRevision_;}return;}if(s.kind==SpellKind::ItemIllusion){if(alive(cast.target,NativeKind::Unit)){auto target=units_.at(cast.target);illusions(source,cast.target,1,s.amount,s.secondary,target->hero?s.heroDuration:s.duration,s.buff,s.ability);}return;}if(s.kind==SpellKind::SacrificeWorker){sacrificePit(source,cast.target);return;}if(s.kind==SpellKind::ItemSoulCapture){captureSoul(source,cast);return;}if(s.kind==SpellKind::Preservation){preserveUnit(source,cast);return;}if(s.kind==SpellKind::Sanctuary){sanctuaryUnit(source,cast);return;}if(s.kind==SpellKind::ManaSteal){manaSteal(source,cast,owner);return;}if(s.kind==SpellKind::ItemChangeTime){auto& clock=requireWorld().clock();auto before=clock.time();clock.temporary(real(s.amount+s.secondary/60),real(s.duration));clockChange(before,clock.time(),false);spellVisual(s,"CasterArt",source,{u->x,u->y});return;}if(s.kind==SpellKind::ItemBlight){if(!u->cast || u->cast->ticket!=cast.ticket || !u->cast->blightReserved)throw std::runtime_error("Missing item blight cast reservation");u->cast->blightReserved=false;releaseItemBlightReservation();if(!startItemBlight(s.ability,cast.point))throw std::runtime_error("Reserved item blight capacity unavailable");return;}if(s.kind==SpellKind::MechanicalCritter){spellVisual(s,"CasterArt",source,{u->x,u->y});summonSpell(source,s,{u->x,u->y},owner);return;}if(s.kind==SpellKind::DarkPortal){spellVisual(s,"EffectArt",0,cast.point);summonSpell(source,s,cast.point,owner);return;}if(s.kind==SpellKind::RainOfChaos){auto inferno=spellInfo(s.helperType,1);if(inferno.kind!=SpellKind::Inferno || s.summonCount>4096-delayedSpells_.size() || spellTicket_>UINT64_MAX-s.summonCount)throw std::runtime_error("Rain of Chaos impact budget exceeded");for(unsigned i=0;i<s.summonCount;++i){float angle=float(random()>>8)*(6.28318530718f/16777216.f),radius=std::sqrt(float(random()>>8)/16777216.f)*s.area;auto point=requireWorld().clamp({real(number(cast.point.x)+std::cos(angle)*radius),real(number(cast.point.y)+std::sin(angle)*radius)});delayedSpells_.emplace(++spellTicket_,DelayedSpell{inferno,source,owner,point,simulationTime_+inferno.impactDelay+double(i)*s.duration});}if(s.effectAlias){auto art=s;art.ability=s.effectAlias;spellVisual(art,"EffectArt",0,cast.point);}return;}if(s.kind==SpellKind::PlaceMine || s.kind==SpellKind::MonsterLure){spellVisual(s,"CasterArt",source,{u->x,u->y});summonSpell(source,s,cast.point,owner);return;}if(s.kind==SpellKind::ItemBuild){placeItemBuilding(source,cast);return;}if(s.kind==SpellKind::ItemPermanent){permanentItem(source,s.ability);return;}if(s.kind==SpellKind::ItemSummon){auto revision=u->castRevision,death=u->deathRevision,ownership=u->ownerRevision;spellVisual(s,"CasterArt",source,{u->x,u->y});for(auto [type,count]:s.summonGroups){if(!alive(source,NativeKind::Unit) || u->removing || number(u->life)<=0 || u->owner!=owner || u->castRevision!=revision || u->deathRevision!=death || u->ownerRevision!=ownership)return;auto group=s;group.summonType=type;group.summonCount=count;summonSpell(source,group,{u->x,u->y},owner);}return;}if(s.kind==SpellKind::Retrain){retrainHero(source,s);return;}if(restorationSpell(s.kind)){restorationEffect(source,cast);return;}if(s.kind==SpellKind::UnstableConcoction){startConcoction(source,cast);return;}if(couplingSpell(s.kind)){coupleEffect(source,cast);return;}if(s.kind==SpellKind::GrabTree){startGrabTree(source,cast);return;}if(s.kind==SpellKind::ManaFlare){startManaFlare(source,cast);return;}if(s.kind==SpellKind::Detonate){detonateSpell(source,s,owner);return;}if(s.kind==SpellKind::AerialShackles || s.kind==SpellKind::Cloud){startHumanChannel(source,cast);return;}if(s.kind==SpellKind::PocketFactory){tinkerVolley(source,cast);return;}if(s.kind==SpellKind::SelfDestruct){unitLife(runtime_.handle("unit",source),{},source);return;}if(s.kind==SpellKind::Volcano){startVolcano(source,cast);return;}if(s.kind==SpellKind::SpiritSplit){startSpiritSplit(source,cast);return;}if(s.kind==SpellKind::Tornado){startTornado(source,cast);return;}if(s.kind==SpellKind::Impale){startImpale(source,cast,owner);return;}if(s.kind==SpellKind::LocustSwarm){startLocustSwarm(source,s,owner);return;}if(s.kind==SpellKind::Phoenix){summonPhoenix(source,s,owner);return;}if(heroUltimate(s.kind)){startHeroUltimate(source,cast);return;}if(teleportSpell(s.kind)){startTeleport(source,cast);return;}if(s.kind==SpellKind::Possession){startPossession(source,cast);return;}if(s.kind==SpellKind::Charm || s.kind==SpellKind::ControlMagic){ownershipEffect(source,cast.target,s,owner);return;}if(s.kind==SpellKind::Drain){startDrain(source);return;}if(s.kind==SpellKind::ManaBurn){startManaBurn(source,cast,owner);return;}if(s.kind==SpellKind::DarkRitual || s.kind==SpellKind::DeathPact){sacrifice(source,cast.target,s,owner);return;}if(selfSpell(s.kind)){selfSpellEffect(source,s);return;}if(s.kind==SpellKind::EatTree){if(alive(cast.target,NativeKind::Destructable))startEatTree(source,cast);return;}if(s.kind==SpellKind::AbsorbMana){startAbsorb(source,cast);return;}if(s.kind==SpellKind::DevourMagic){devourMagic(source,s,cast.point,owner);return;}if(s.kind==SpellKind::Root){startRoot(source,cast);return;}if(unitFormSpell(s.kind)){startUnitForm(source,cast);return;}if(s.kind==SpellKind::LoadCorpse){loadUnit(source,cast.target);return;}if(s.kind==SpellKind::UnloadCorpse){auto drop=cast;drop.point={u->x,u->y};startCargoDrop(source,drop);return;}if(s.kind==SpellKind::Cannibalize){startCannibalize(source,cast);return;}if(corpseSpell(s.kind)){corpseSpellEffect(source,s,cast.target,cast.point,owner);return;}if(s.kind==SpellKind::BattleStations){battleStations(source,s);return;}if(s.kind==SpellKind::StandDown){unloadAll(source,{u->x,u->y});return;}if(s.kind==SpellKind::Devour){loadUnit(source,cast.target,&s);return;}if(s.kind==SpellKind::Load){loadUnit(source,cast.target);return;}if(s.kind==SpellKind::Unload){startCargoDrop(source,cast);return;}if(s.kind==SpellKind::UnloadInstant){unloadAll(source,{u->x,u->y});return;}if(s.kind==SpellKind::WindWalk){applyBuff(source,source,s,BuffKind::WindWalk,true);spellVisual(s,"CasterArt",source,{u->x,u->y});return;}if(s.kind==SpellKind::Blink){blinkSpell(source,s,cast.point);return;}if(s.kind==SpellKind::MirrorImage){startMirrorImage(source,cast);return;}if(s.kind==SpellKind::ShadowMeld){startShadowMeld(source,s);return;}if(s.kind==SpellKind::Sentinel){startSentinel(source,cast);return;}if(s.kind==SpellKind::Reveal){addReveal(owner,s,cast.point);spellVisual(s,"CasterArt",source,{u->x,u->y});return;}if(s.kind==SpellKind::Dust){dustSpell(source,s,{u->x,u->y},owner);spellVisual(s,"CasterArt",source,{u->x,u->y});return;}if(s.kind==SpellKind::Unsummon){startUnsummon(source,cast);return;}if(s.channelled){startChannel(source);return;}if(s.kind==SpellKind::FlameStrike){if(groundSpells_.size()>=4096)throw std::runtime_error("Active ground spell budget exceeded");GroundSpell ground;ground.spell=s;ground.source=source;ground.owner=owner;ground.point=cast.point;ground.nextPulse=s.castDelay+(s.fullPeriod<=s.fullTime?s.fullPeriod:s.fullTime+s.burnPeriod);ground.visuals=spellVisual(s,"EffectArt",0,cast.point,false);groundSpells_.emplace(++spellTicket_,std::move(ground));spellVisual(s,"CasterArt",source,{u->x,u->y});return;}spellVisual(s,"CasterArt",source,{u->x,u->y});
    if(s.kind==SpellKind::FingerOfDeath){if(!alive(cast.target,NativeKind::Unit))return;if(s.amount>0)damageUnit(source,cast.target,s.amount,0,14,false,false,nullptr,false,true,owner);if(!alive(source,NativeKind::Unit) || !alive(cast.target,NativeKind::Unit))return;if(delayedSpells_.size()>=4096)throw std::runtime_error("Delayed spell budget exceeded");delayedSpells_.emplace(++spellTicket_,DelayedSpell{s,source,owner,cast.point,simulationTime_+s.impactDelay,cast.target});return;}
    if((s.kind==SpellKind::Rejuvenation || s.kind==SpellKind::Bloodlust) && s.targeting==SpellTargeting::None){SpellMissile missile;missile.spell=s;missile.source=source;missile.target=source;missile.owner=owner;missile.position={u->x,u->y};spellImpact(std::move(missile));return;}
    if(s.kind==SpellKind::Purge && alive(cast.target,NativeKind::Destructable)){purgeSpell(source,cast.target,s);return;}if(s.targeting==SpellTargeting::Unit){SpellMissile missile;missile.spell=s;missile.source=source;missile.target=cast.target;missile.owner=owner;missile.position={u->x,u->y};missile.amount=s.amount;missile.born=simulationTime_;launchSpellMissile(std::move(missile));return;}
    WorldPoint point=s.targeting==SpellTargeting::None?WorldPoint{u->x,u->y}:cast.point;
    if(s.kind==SpellKind::Shockwave || s.kind==SpellKind::CarrionSwarm || s.kind==SpellKind::BreathFire){if(s.kind!=SpellKind::BreathFire && s.distance==0)return;if(spellWaves_.size()>=4096)throw std::runtime_error("Active spell wave budget exceeded");SpellWave wave;wave.spell=s;wave.born=simulationTime_;wave.source=source;wave.owner=owner;wave.origin={u->x,u->y};float dx=number(point.x)-number(u->x),dy=number(point.y)-number(u->y),length=std::hypot(dx,dy);if(length>.001f){wave.directionX=dx/length;wave.directionY=dy/length;}else{float angle=number(u->facing)*3.14159265359f/180;wave.directionX=std::cos(angle);wave.directionY=std::sin(angle);}spellWaves_.emplace(++spellTicket_,std::move(wave));return;}
    if(s.impactDelay>0){if(delayedSpells_.size()>=4096)throw std::runtime_error("Delayed spell budget exceeded");delayedSpells_.emplace(++spellTicket_,DelayedSpell{s,source,owner,point,simulationTime_+s.impactDelay});return;}areaSpell(source,s,point,owner);
}
void ScriptSession::areaSpell(std::uint32_t source,const SpellInfo& s,WorldPoint point,unsigned owner) {
    if(!alive(source,NativeKind::Unit))return;
    if(s.kind==SpellKind::Taunt){tauntSpell(source,s);return;}
    if(s.kind==SpellKind::HowlTerror || s.kind==SpellKind::Roar){roarEffect(source,s,owner);return;}
    if(wardSpell(s.kind)){summonSpell(source,s,point,owner);return;}
    if(s.kind==SpellKind::Silence){silenceEffect(source,s,point,owner);return;}
    if(s.kind==SpellKind::WarStomp && s.area>0 && requireWorld().canAddDeformation()){TerrainDeformation ripple;ripple.x=number(point.x);ripple.y=number(point.y);ripple.radius=s.area;ripple.depth=-50;ripple.duration=.3;ripple.count=1;ripple.spaceWaves=1;ripple.timeWaves=2;ripple.startRadius=1;ripple.limitNegative=true;ripple.started=simulationTime_;requireWorld().addDeformation(ripple);}
    if(s.kind==SpellKind::Dispel){auto targets=spellTargets(source,s,point,owner);for(auto target:targets){if(!alive(source,NativeKind::Unit))break;if(alive(target,NativeKind::Unit))dispelSpell(source,target,s);}spellVisual(s,"EffectArt",0,point);return;}
    if(s.kind==SpellKind::WaterElemental || s.kind==SpellKind::SpiritWolf || s.kind==SpellKind::SerpentWard || s.kind==SpellKind::Treants || s.kind==SpellKind::Scout || s.kind==SpellKind::VengeanceAvatar || s.kind==SpellKind::Grizzly || s.kind==SpellKind::Quilbeast || s.kind==SpellKind::Hawk || s.kind==SpellKind::LavaSpawn){summonSpell(source,s,point,owner);return;}
    auto victims=spellTargets(source,s,point,owner);float allocated=0;unsigned count=0;
    for(auto id:victims){
        if(!alive(source,NativeKind::Unit))break;if(!alive(id,NativeKind::Unit))continue;
        if(s.kind==SpellKind::FanKnives){if(s.targets && count>=s.targets)break;float amount=s.maxDamage>0?std::min(s.amount,std::max(0.f,s.maxDamage-allocated)):s.amount;if(amount<=0)break;allocated+=amount;++count;SpellMissile missile;missile.spell=s;missile.source=source;missile.target=id;missile.owner=owner;missile.position=point;missile.amount=amount;missile.born=simulationTime_;launchSpellMissile(std::move(missile));continue;}
        damageUnit(source,id,s.amount,0,14);if(s.kind==SpellKind::ThunderClap)applyBuff(id,source,s,BuffKind::Slow);else if(s.kind==SpellKind::WarStomp)applyBuff(id,source,s,BuffKind::Stun);else if(s.kind==SpellKind::Inferno){auto stun=s;stun.buff=ObjectData::code("BPSE");applyBuff(id,source,stun,BuffKind::Stun);}else throw std::runtime_error("Area spell consumer is missing");
    }
    if(s.kind==SpellKind::Inferno && alive(source,NativeKind::Unit))summonSpell(source,s,point,owner);spellVisual(s,"EffectArt",0,point);
}
void ScriptSession::areaSpellsTick(double delta) {
    std::vector<std::uint64_t> delayed,waves;for(auto& [id,s]:delayedSpells_)if(s.due<=simulationTime_)delayed.push_back(id);for(auto& [id,w]:spellWaves_)waves.push_back(id);
    for(auto id:delayed){auto found=delayedSpells_.find(id);if(found==delayedSpells_.end())continue;auto spell=std::move(found->second);delayedSpells_.erase(found);if(spell.target && spell.spell.kind==SpellKind::FingerOfDeath){if(alive(spell.source,NativeKind::Unit) && alive(spell.target,NativeKind::Unit)){auto source=units_.at(spell.source),target=units_.at(spell.target);SpellMissile visual;visual.spell=spell.spell;visual.source=spell.source;visual.target=spell.target;visual.owner=spell.owner;visual.position={source->x,source->y};spellLightning(visual);spellVisual(spell.spell,"TargetArt",spell.target,{target->x,target->y});}}else if(spell.target)manaBurn(spell.source,spell.target,spell.spell,spell.owner);else areaSpell(spell.source,spell.spell,spell.point,spell.owner);}
    for(auto id:waves){
        auto found=spellWaves_.find(id);if(found==spellWaves_.end())continue;auto wave=std::move(found->second);spellWaves_.erase(found);if(!alive(wave.source,NativeKind::Unit))continue;auto caster=units_.at(wave.source);auto& s=wave.spell;float previous=wave.travelled,next=std::min(s.distance,previous+float(delta)*s.speed);if(s.kind==SpellKind::Impale)impaleWaveArt(wave,next);std::vector<std::pair<float,std::uint32_t>> hits;
        for(auto& [target,u]:units_){if(wave.hit.contains(target))continue;float dx=number(u->x)-number(wave.origin.x),dy=number(u->y)-number(wave.origin.y),along=dx*wave.directionX+dy*wave.directionY;if(along<0 || along>s.distance+u->collision)continue;if(s.kind==SpellKind::Impale && (along+u->collision<previous || along-u->collision>next))continue;float closest=std::clamp(along,previous,next),radius=s.area+(s.endRadius-s.area)*std::clamp(along/s.distance,0.f,1.f);float x=dx-wave.directionX*closest,y=dy-wave.directionY*closest;if(x*x+y*y>(radius+u->collision)*(radius+u->collision) || !spellTarget(*caster,*u,s,false,wave.owner))continue;hits.emplace_back(along,target);}
        std::sort(hits.begin(),hits.end());for(auto [along,target]:hits){if(!alive(wave.source,NativeKind::Unit))break;if(!alive(target,NativeKind::Unit) || !spellTarget(*caster,*units_.at(target),s,false,wave.owner))continue;float amount=s.maxDamage>0?std::min(s.amount,std::max(0.f,s.maxDamage-wave.dealt)):s.amount;if(amount<=0 && s.kind!=SpellKind::Impale)break;wave.hit.insert(target);wave.dealt+=amount;if(s.kind==SpellKind::Impale)impaleHit(wave.source,target,s,wave.owner);else if(s.kind==SpellKind::BreathFire)breathFireHit(wave.source,target,s,wave.owner,amount);else damageUnit(wave.source,target,amount,0,14);}wave.travelled=next;
        if(next<s.distance && alive(wave.source,NativeKind::Unit) && (s.maxDamage<=0 || wave.dealt<s.maxDamage || s.kind==SpellKind::BreathFire))spellWaves_.emplace(id,std::move(wave));
    }
}
